const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
for (let end = a.length - 1; end > 0; end--) {
  for (let i = 0; i < end; i++) {
    viz.highlight('a', { indices: [i, i + 1] }, 'compare');
    if (a[i] > a[i + 1]) {
      viz.step({ explanation: `${a[i]} > ${a[i + 1]}, also tauschen.` });
      [a[i], a[i + 1]] = [a[i + 1], a[i]];
      viz.swap('a', i, i + 1);
      viz.highlight('a', { indices: [i, i + 1] }, 'swap');
      viz.step({ explanation: `Getauscht: ${a.join(', ')}` });
    } else {
      viz.step({ explanation: `${a[i]} ≤ ${a[i + 1]}, kein Tausch.` });
    }
  }
  viz.highlight('a', { range: [end, a.length - 1] }, 'sorted');
  viz.step({ explanation: `${a[end]} steht an seinem endgültigen Platz.` });
}
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
for (let i = 1; i < a.length; i++) {
  const key = a[i];
  let j = i - 1;
  viz.scalar('key', key);
  viz.highlight('a', { range: [0, i - 1] }, 'sorted');
  viz.highlight('a', { indices: [i, i] }, 'active');
  viz.step({ explanation: `Nimm ${key} aus Position ${i} und füge es in den sortierten Anfang ein.` });
  while (j >= 0 && a[j] > key) {
    viz.highlight('a', { indices: [j, j + 1] }, 'compare');
    viz.step({ explanation: `${a[j]} > ${key}, also ${a[j]} nach rechts verschieben.` });
    a[j + 1] = a[j];
    viz.set('a', j + 1, a[j]);
    j--;
    viz.step({ explanation: `Verschoben: ${a.join(', ')}` });
  }
  a[j + 1] = key;
  viz.set('a', j + 1, key);
  viz.highlight('a', { range: [0, i] }, 'sorted');
  viz.step({ explanation: `${key} wird an Position ${j + 1} eingefügt: ${a.join(', ')}` });
}
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
const target = input.target;
viz.array('a', a);
viz.scalar('target', target);
viz.step({ explanation: `Ausgangslage: Suche ${target} in ${a.join(', ')}` });
let lo = 0;
let hi = a.length - 1;
let found = -1;
while (lo <= hi) {
  const mid = Math.floor((lo + hi) / 2);
  viz.highlight('a', { range: [lo, hi] }, 'range');
  viz.pointer('a', 'mid', mid);
  viz.highlight('a', { indices: [mid, mid] }, 'compare');
  viz.step({ explanation: `Mitte ist Index ${mid} mit Wert ${a[mid]}.` });
  if (a[mid] === target) {
    found = mid;
    viz.step({ explanation: `${a[mid]} = ${target}, gefunden bei Index ${mid}.` });
    break;
  }
  if (a[mid] < target) {
    viz.step({ explanation: `${a[mid]} < ${target}, Suche rechts von Index ${mid}.` });
    lo = mid + 1;
  } else {
    viz.step({ explanation: `${a[mid]} > ${target}, Suche links von Index ${mid}.` });
    hi = mid - 1;
  }
}
if (found === -1) {
  viz.step({ explanation: `${target} ist nicht im Array enthalten.` });
} else {
  viz.highlight('a', { indices: [found, found] }, 'sorted');
  viz.step({ explanation: `Ergebnis: ${target} steht bei Index ${found}.` });
}

const a = [...input.values];
const target = input.target;
let lo = 0;
let hi = a.length - 1;
let found = -1;
viz.array('a', a);
viz.scalar('ziel', target);
viz.step({ explanation: `Ausgangslage: sortiert ${a.join(', ')}, gesucht wird ${target}.` });
while (lo <= hi) {
  const mid = Math.floor((lo + hi) / 2);
  viz.pointer('a', 'lo', lo);
  viz.pointer('a', 'hi', hi);
  viz.pointer('a', 'mid', mid);
  viz.highlight('a', { range: [lo, hi] }, 'range');
  viz.highlight('a', { indices: [mid, mid] }, 'compare');
  viz.step({ explanation: `Bereich ${lo} bis ${hi}, Mitte ist Index ${mid} mit Wert ${a[mid]}.` });
  if (a[mid] === target) {
    found = mid;
    viz.highlight('a', { indices: [mid, mid] }, 'active');
    viz.step({ explanation: `${a[mid]} = ${target}: gefunden an Index ${mid}.` });
    break;
  } else if (a[mid] < target) {
    viz.step({ explanation: `${a[mid]} < ${target}: Suche rechts von Index ${mid}.` });
    lo = mid + 1;
  } else {
    viz.step({ explanation: `${a[mid]} > ${target}: Suche links von Index ${mid}.` });
    hi = mid - 1;
  }
}
if (found === -1) {
  viz.step({ explanation: `${target} kommt in der Liste nicht vor.` });
} else {
  viz.highlight('a', { indices: [found, found] }, 'sorted');
  viz.step({ explanation: `Ergebnis: ${target} steht an Index ${found}.` });
}

const vals = [...input.values];
const nodes = [];
const edges = [];
const left = new Map();
const right = new Map();
let root;
viz.graph('t', { nodes, edges, directed: true });
viz.step({ explanation: `Ausgangslage: leerer Baum. Einzufügen: ${vals.join(', ')}` });
for (const v of vals) {
  const id = String(v);
  if (root === undefined) {
    nodes.push({ id });
    root = id;
    viz.graph('t', { nodes, edges, directed: true });
    viz.nodeState('t', id, 'frontier');
    viz.step({ explanation: `${v} wird als Wurzel eingefügt.` });
    continue;
  }
  let cur = root;
  viz.nodeState('t', cur, 'active');
  viz.step({ explanation: `Füge ${v} ein: Beginne an der Wurzel ${cur}.` });
  for (;;) {
    const goLeft = v < Number(cur);
    const side = goLeft ? 'links' : 'rechts';
    viz.step({ explanation: `${v} ${goLeft ? '<' : '>'} ${cur}: weiter nach ${side}.` });
    const child = goLeft ? left.get(cur) : right.get(cur);
    if (child === undefined) {
      nodes.push({ id });
      edges.push({ id: `${cur}-${id}`, from: cur, to: id });
      (goLeft ? left : right).set(cur, id);
      viz.graph('t', { nodes, edges, directed: true });
      viz.edgeState('t', `${cur}-${id}`, 'tree');
      viz.nodeState('t', id, 'frontier');
      viz.nodeState('t', cur, 'visited');
      viz.step({ explanation: `${v} wird ${side} von ${cur} eingefügt.` });
      break;
    }
    viz.nodeState('t', cur, 'visited');
    cur = child;
    viz.nodeState('t', cur, 'active');
  }
}
const inorder = (n) => (n === undefined ? [] : [...inorder(left.get(n)), n, ...inorder(right.get(n))]);
viz.step({ explanation: `Fertig. In-order-Ausgabe: ${inorder(root).join(', ')}` });

const { nodes, edges, directed, start } = input;
viz.graph('g', { nodes, edges, directed });
viz.step({ explanation: `Ausgangslage: Start bei ${start}.` });
const neighbours = (id) => edges.filter((e) => e.from === id || (!directed && e.to === id));
const seen = new Set([start]);
const treeEdges = new Set();
const queue = [start];
viz.nodeState('g', start, 'frontier');
viz.step({ explanation: `${start} kommt in die Warteschlange.` });
while (queue.length > 0) {
  const current = queue.shift();
  viz.nodeState('g', current, 'active');
  viz.step({ explanation: `Bearbeite ${current}.` });
  for (const e of neighbours(current)) {
    if (treeEdges.has(e.id)) continue;
    const next = e.from === current ? e.to : e.from;
    if (seen.has(next)) {
      viz.edgeState('g', e.id, 'rejected');
      viz.step({ explanation: `${next} ist schon bekannt.` });
    } else {
      seen.add(next);
      queue.push(next);
      treeEdges.add(e.id);
      viz.edgeState('g', e.id, 'tree');
      viz.nodeState('g', next, 'frontier');
      viz.step({ explanation: `${next} entdeckt und in die Warteschlange gelegt.` });
    }
  }
  viz.nodeState('g', current, 'visited');
  viz.step({ explanation: `${current} ist fertig.` });
}
viz.step({ explanation: `Alle von ${start} erreichbaren Knoten wurden besucht.` });

const { nodes, edges, directed, start } = input;
viz.graph('g', { nodes, edges, directed });
viz.step({ explanation: `Ausgangslage: Start bei ${start}.` });
const seen = new Set();
const neighbours = (id) => edges.filter((e) => e.from === id || (!directed && e.to === id));
const visit = (current, viaEdge) => {
  seen.add(current);
  viz.nodeState('g', current, 'active');
  viz.step({ explanation: `Besuche ${current}.` });
  for (const e of neighbours(current)) {
    if (e.id === viaEdge) continue;
    const next = e.from === current ? e.to : e.from;
    if (seen.has(next)) {
      viz.edgeState('g', e.id, 'rejected');
      viz.step({ explanation: `${next} ist schon besucht, Kante ${e.id} wird übersprungen.` });
    } else {
      viz.edgeState('g', e.id, 'tree');
      viz.step({ explanation: `Gehe von ${current} zu ${next} tiefer.` });
      visit(next, e.id);
    }
  }
  viz.nodeState('g', current, 'visited');
  viz.step({ explanation: `${current} ist fertig, Rückkehr zum vorherigen Knoten.` });
};
visit(start, null);
viz.step({ explanation: `Alle von ${start} erreichbaren Knoten wurden besucht.` });

const { nodes, edges, directed, start } = input;
viz.graph('g', { nodes, edges, directed });
viz.step({ explanation: `Ausgangslage: Start bei ${start}.` });
const dist = new Map();
const prev = new Map();
for (const n of nodes) dist.set(n.id, Infinity);
dist.set(start, 0);
const done = new Set();
viz.nodeState('g', start, 'frontier');
viz.step({ explanation: `Distanz zu ${start} ist 0, alle anderen unendlich.` });
const neighbours = (id) => edges.filter((e) => e.from === id || (!directed && e.to === id));
while (true) {
  let cur = null;
  for (const n of nodes) {
    if (!done.has(n.id) && dist.get(n.id) < Infinity && (cur === null || dist.get(n.id) < dist.get(cur))) cur = n.id;
  }
  if (cur === null) break;
  viz.nodeState('g', cur, 'active');
  viz.step({ explanation: `Kleinste Distanz unter den offenen Knoten: ${cur} mit ${dist.get(cur)}.` });
  for (const e of neighbours(cur)) {
    const other = e.from === cur ? e.to : e.from;
    if (done.has(other)) {
      viz.edgeState('g', e.id, 'rejected');
      viz.step({ explanation: `${other} ist schon fertig, Kante wird übersprungen.` });
      continue;
    }
    const nd = dist.get(cur) + e.weight;
    if (nd < dist.get(other)) {
      dist.set(other, nd);
      prev.set(other, e.id);
      viz.nodeState('g', other, 'frontier');
      viz.step({ explanation: `Neue Distanz zu ${other}: ${dist.get(cur)} + ${e.weight} = ${nd}.` });
    } else {
      viz.edgeState('g', e.id, 'rejected');
      viz.step({ explanation: `${dist.get(cur)} + ${e.weight} = ${nd} ist nicht kürzer als ${dist.get(other)}.` });
    }
  }
  done.add(cur);
  viz.nodeState('g', cur, 'visited');
  viz.step({ explanation: `${cur} ist fertig mit Distanz ${dist.get(cur)}.` });
}
for (const n of nodes) {
  if (prev.has(n.id)) viz.edgeState('g', prev.get(n.id), 'tree');
}
viz.step({ explanation: `Kürzeste Distanzen: ${nodes.map((n) => `${n.id}=${dist.get(n.id)}`).join(', ')}` });

const n = input.params.n;
viz.scalar('n', n);
viz.scalar('i', 1);
viz.scalar('result', 1);
viz.step({ explanation: `Ausgangslage: n = ${n}, result = 1` });
let result = 1;
for (let i = 1; i <= n; i++) {
  const prev = result;
  result = prev * i;
  viz.setScalar('i', i);
  viz.setScalar('result', result);
  viz.step({ explanation: `Multipliziere ${prev} mit ${i}: ${result}` });
}
viz.step({ explanation: `Ergebnis: ${n}! = ${result}` });

let a = input.params.a;
let b = input.params.b;
viz.scalar('a', a);
viz.scalar('b', b);
viz.step({ explanation: `Ausgangslage: a = ${a}, b = ${b}.` });
while (b !== 0) {
  const r = a % b;
  viz.step({ explanation: `Rest von ${a} geteilt durch ${b}: ${r}.` });
  a = b;
  b = r;
  viz.setScalar('a', a);
  viz.setScalar('b', b);
  viz.step({ explanation: `Neues Paar: a = ${a}, b = ${b}.` });
}
viz.step({ explanation: `Rest ist 0. Ergebnis: ggT = ${a}.` });
